<script setup lang="ts">
import type {Claim,ObservedField,SourceReview,SourceTrace} from '../types';
defineProps<{claim:Claim;demo:boolean}>();
function safeUrl(url:string){try{const parsed=new URL(url);return ['http:','https:'].includes(parsed.protocol)?url:undefined;}catch{return undefined;}}
function observation(field:ObservedField){return field.state==='observed'?field.value:({missing:'미확인',conflicting:'상충하는 표기',invalid:'형식 또는 추적 범위 확인 필요'} as const)[field.state];}
function tableLocations(trace:SourceTrace){return trace.quoteBlockIndexes.flatMap(index=>{const location=trace.blocks[index]?.tableLocation;return location?[location]:[];});}
const referenceLabels:Record<string,string>={resolved_same_table_header:'같은 표의 헤더를 구조상 찾음 · 의미 미검증',missing_id:'참조 ID를 찾지 못함',duplicate_id:'중복 ID · 연결 미확정',cross_table:'다른 표의 헤더 · 연결 미확정',not_header:'헤더가 아닌 대상 · 연결 미확정',unresolved:'구조 연결 미확정'};
const cueLabels:Record<string,string>={period:'기간 관련 표기',denominator:'분모 관련 표기',correction:'정정 관련 표기',unit:'단위 관련 표기'};
function quoteReferences(trace:SourceTrace){return trace.tableReferenceAudit?.references.filter(reference=>trace.quoteBlockIndexes.includes(reference.cellBlockIndex))??[];}
function identityLabel(status:SourceReview['identity']['status']){return {unregistered:'검토된 등록 목록에 없음',registered_origin:'등록 도메인·발행자 표기 일치',insecure_origin:'HTTPS 출처 확인 필요',publisher_conflict:'등록 정보와 발행자 표기 불일치',publisher_unverified:'등록 도메인, 발행자 표기 미확인',trace_unavailable:'대조할 원문 추적 정보 없음'}[status];}
function signalLabel(signal:string){return ({SAME_FINAL_URL:'같은 최종 주소',SAME_DOCUMENT_HASH:'수집 문서가 같음',SAME_TEXT_HASH:'정규화 원문이 같음',DECLARED_SOURCE_LINK:'명시된 원문 인용 링크',SHARED_DECLARED_SOURCE:'공통 원출처 링크 표기',SAME_REGISTERED_PUBLISHER:'같은 등록 발행 주체'} as Record<string,string>)[signal]??signal;}
</script>
<template><aside class="evidence-panel" aria-labelledby="evidence-title"><div class="section-label">EVIDENCE <span>원문과 비교</span></div><h3 id="evidence-title">근거 대조</h3><p class="original-claim">{{claim.text}}</p><details v-if="claim.contextText"><summary>전사 원문 맥락</summary><p class="original-claim">{{claim.contextText}}</p></details><article v-for="(e,i) in claim.evidence" :key="i" class="source-card"><span class="small-label">{{demo?'가상 근거 · 설명용':e.usable?'원문 인용 확인':'확정 근거로 사용하지 않음'}}</span><blockquote>{{e.quote}}</blockquote><p>{{e.title}}</p><div class="source-meta">{{e.publisher??'발행 주체 미확인'}} · {{e.publishedAt??'날짜 미확인'}}<br><span v-if="e.sourceTrace?.quoteOccurrences!=null&&e.sourceTrace.quoteOccurrences>1">인용 위치 미확정 · 동일 인용 {{e.sourceTrace.quoteOccurrences}}곳</span><span v-else>인용 위치 {{e.position}}</span></div><details v-if="e.sourceTrace" class="source-trace"><summary>원문 수집·발행 정보</summary><p class="muted">페이지에서 관측한 정보이며 출처 인증이나 독립성 확인을 뜻하지 않습니다.</p><dl><dt>수집 시각 (UTC)</dt><dd>{{e.sourceTrace.retrievedAt}}</dd><dt>요청한 주소</dt><dd>{{e.sourceTrace.requestedUrl}}</dd><dt>최종 주소</dt><dd>{{e.sourceTrace.finalUrl}}</dd><dt>발행 주체 (페이지 표기)</dt><dd><span>{{observation(e.sourceTrace.publication.publisher)}}</span></dd><dt>발행일 (페이지 표기)</dt><dd>{{observation(e.sourceTrace.publication.publishedAt)}}</dd><dt>수정일 (페이지 표기)</dt><dd>{{observation(e.sourceTrace.publication.modifiedAt)}}</dd></dl><div v-for="(location,locationIndex) in tableLocations(e.sourceTrace)" :key="locationIndex" class="table-location"><p>표 {{location.tableIndex+1}} · 행 {{location.rowIndex===null?'미확인':location.rowIndex+1}} · 셀 {{location.cellIndex===null?'미확인':location.cellIndex+1}} (원문 순서)</p><p>행 병합 표기: {{location.rowSpan??'미확인'}} · 열 병합 표기: {{location.columnSpan??'미확인'}}</p><p class="muted">행·셀 번호는 원문 태그 순서입니다. 단위·분모·주석의 의미는 검증되지 않았습니다.</p></div><section v-if="e.sourceTrace.tableContext" class="table-context"><h4>같은 표의 헤더·캡션·주석 후보</h4><p class="muted">같은 표의 설명 후보이며 해당 수치와의 의미 관계는 검증되지 않았습니다.</p><ul><li v-for="fragment in e.sourceTrace.tableContext.fragments" :key="fragment.blockIndex"><span class="small-label">{{fragment.kind==='table_header'?'헤더':fragment.kind==='caption'?'캡션':'주석'}} · 원문 블록 {{fragment.blockIndex+1}}</span><blockquote>{{fragment.text}}</blockquote><p v-if="fragment.truncated" class="muted">앞 500자만 보존했습니다.</p></li></ul><p v-if="!e.sourceTrace.tableContext.fragments.length" class="muted">같은 표에서 지원하는 설명 블록을 찾지 못했습니다.</p><p v-if="!e.sourceTrace.tableContext.complete" class="muted">표 설명 후보를 일부만 보존했습니다.</p></section><section v-if="quoteReferences(e.sourceTrace).length"><h4>표 헤더 참조 관측</h4><p class="muted">명시된 ID 연결만 확인했습니다. 수치·단위·분모의 의미 관계는 검증되지 않았습니다.</p><ul><li v-for="(reference,index) in quoteReferences(e.sourceTrace)" :key="index"><span>{{reference.declaredId}}</span><p>{{referenceLabels[reference.status]}}</p></li></ul><p v-if="!e.sourceTrace.tableReferenceAudit?.complete" class="muted">참조를 일부만 추적했습니다.</p></section><section v-if="e.sourceTrace.tableContext?.cueAudit?.cues.length"><h4>맥락 검토 표기</h4><p class="muted">문자열에서 발견한 표기이며 해당 주장에 적용되는 의미는 미검증입니다.</p><ul><li v-for="(cue,index) in e.sourceTrace.tableContext.cueAudit.cues" :key="index">{{cueLabels[cue.kind]}} · {{cue.text}}</li></ul><p v-if="!e.sourceTrace.tableContext.cueAudit.complete" class="muted">맥락 표기를 일부만 보존했습니다.</p></section><p v-if="!e.sourceTrace.structureComplete" class="muted">문서 구조의 일부만 추적했습니다. 확정 근거로 사용하지 않습니다.</p><p v-if="e.sourceTrace.extractionTruncated" class="muted">원문 일부만 AI 추출에 전달했습니다. 전체 맥락 확인이 필요합니다.</p></details><details v-if="e.sourceReview" class="source-trace"><summary>출처 등록·재인용 검토</summary><p class="muted">출처 독립성은 확인되지 않았습니다.</p><p>{{identityLabel(e.sourceReview.identity.status)}}</p><p class="muted">등록 정보와의 대조는 주장의 사실성이나 최초 원본 인증이 아닙니다.</p><dl v-if="e.sourceReview.identity.registeredName"><dt>등록 목록의 발행 주체</dt><dd><span>{{e.sourceReview.identity.registeredName}}</span></dd></dl><p v-if="e.sourceReview.groupSize>1">가능한 공통 출처 그룹 · {{e.sourceReview.groupSize}}개 근거</p><p v-else class="muted">다른 후보와의 관계가 발견되지 않아도 독립 출처라는 뜻은 아닙니다.</p><ul v-if="e.sourceReview.signals.length"><li v-for="signal in e.sourceReview.signals" :key="signal">{{signalLabel(signal)}}</li></ul><p v-if="e.sourceTrace&&e.sourceTrace.parserVersion!=='static-text-v1'&&!e.sourceTrace.sourceLinksComplete" class="muted">명시된 출처 링크를 일부만 추적했습니다.</p><ul v-if="e.sourceReview.relatedUrls.length"><li v-for="url in e.sourceReview.relatedUrls" :key="url" class="source-reference">{{url}}</li></ul><p class="muted">인용 링크는 페이지의 표기이며 실제 재인용 여부는 추가 확인이 필요합니다.</p></details><p v-if="e.reasons.length" class="muted">검증 제한: {{e.reasons.join(', ')}}</p><a v-if="!demo&&safeUrl(e.url)" :href="safeUrl(e.url)" target="_blank" rel="noopener noreferrer">원문 열기 ↗</a><span v-else-if="demo" class="muted">설명용 가상 자료이며 실제 출처가 아닙니다.</span></article><p v-if="!claim.evidence.length" class="empty-evidence">{{claim.verdict==='EXCLUDED'?'의견·전망은 사실 검증 대상에서 제외합니다.':'확정에 사용할 근거가 없습니다. 자료 부족은 거짓을 의미하지 않습니다.'}}</p><div class="evidence-note">판정은 확인된 근거 범위에 한정됩니다. 근거의 강도는 진실 확률이 아닙니다.</div></aside></template>

<style scoped>
.source-trace{margin-block:1rem}.source-trace dd{margin:0 0 .6rem;overflow-wrap:anywhere}.source-reference{overflow-wrap:anywhere}.source-trace dt{font-size:.8rem;color:var(--muted,#64748b)}
</style>
